import{_ as e,o as i,c as t,a3 as n}from"./chunks/framework.BvvarXmc.js";const c=JSON.parse('{"title":"Alur Otentikasi & Otorisasi","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/auth-flow.md","filePath":"architecture/auth-flow.md","lastUpdated":null}'),s={name:"architecture/auth-flow.md"};function r(o,a,l,u,d,m){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="alur-otentikasi-otorisasi" tabindex="-1">Alur Otentikasi &amp; Otorisasi <a class="header-anchor" href="#alur-otentikasi-otorisasi" aria-label="Permalink to &quot;Alur Otentikasi &amp; Otorisasi&quot;">​</a></h1><p>Sistem menerapkan autentikasi terpadu berbasis Token JWT dan Role-Based Access Control (RBAC) yang sinkron antara frontend dan backend.</p><hr><h2 id="autentikasi-pengguna" tabindex="-1">Autentikasi Pengguna <a class="header-anchor" href="#autentikasi-pengguna" aria-label="Permalink to &quot;Autentikasi Pengguna&quot;">​</a></h2><ol><li>Pengguna melakukan login di <code>superapp-frontend</code>.</li><li>Request login divalidasi oleh endpoint auth Laravel atau Go.</li><li>Klien menerima access token dan refresh token yang memuat metadata pengguna serta hak akses (<code>roles</code> &amp; <code>permissions</code>).</li><li>Token dikirim pada header <code>Authorization: Bearer &lt;token&gt;</code> untuk setiap request selanjutnya.</li></ol><hr><h2 id="sistem-otorisasi-policy" tabindex="-1">Sistem Otorisasi &amp; Policy <a class="header-anchor" href="#sistem-otorisasi-policy" aria-label="Permalink to &quot;Sistem Otorisasi &amp; Policy&quot;">​</a></h2><p>Izin akses dipetakan secara terperinci (<em>fine-grained permissions</em>):</p><ul><li><strong>Superadmin</strong>: Akses menyeluruh ke Central DB &amp; konfigurasi sistem.</li><li><strong>Admin Sekolah</strong>: Pengaturan data master, manajemen siswa, dan konfigurasi tagihan.</li><li><strong>Bendahara / Kasir</strong>: Pembayaran SPP, top-up dompet, dan rekap keuangan.</li><li><strong>Guru / Wali Kelas</strong>: Absensi, input nilai, dan manajemen CBT/LMS.</li><li><strong>Siswa / Orang Tua</strong>: Melihat jadwal, mengerjakan ujian, dan cek histori pembayaran.</li></ul>',9)])])}const k=e(s,[["render",r]]);export{c as __pageData,k as default};
